      },
      {
        "time": "距今约33年",
        "name": "魔物王国宣告独立",
        "effect": "亚人联合在大陆东部建立了独立的民族国家，形成了当前人类诸国与魔物王国并立的格局。"
      },
      {
        "time": "距今约30年",
        "name": "《互不侵犯基本法案》签订",
        "effect": "人类诸国与魔物王国结束了持续三年的边境战争，双方关系进入相对稳定的状态。"
      },
      {
        "time": "距今约15年",
        "name": "民用魔导网络普及",
        "effect": "高速信息网络覆盖了大部分地区，催生了移动终端和各类线上应用服务。"
      }
    ]
  }
}

