entries.content:
{
  "name": "瑞穗联合邦",
  "parent_realm": "位于大陆东部的独立主权国家",
  "summary": "由多种亚人族群联合建立的国家，实行多部族联合议会制。社会风气自由开放，鼓励不同文化共存与交融。在城市发展中注重与自然环境的和谐，形成了独特的生态型现代都市景观。",
  "figures": [
    {
      "name": "联合议会",
      "summary": "由各主要亚人部族的代表组成的最高权力机构，负责制定国家法律与重大决策，其成员经由选举产生。"
    }
  ],
  "locations": [
    {
      "name": "绿石城",
      "summary": "位于王国西南边境的门户城市，是与人类诸国进行贸易和文化交流的重要枢纽。",
      "layout": "坐落于王国西南边境线上，紧邻与人类诸国分界的巨大森林。"
    },
    {
      "name": "迷迭香之森",
      "summary": "环绕绿石城的一片广阔森林，以生长着大量具备微弱魔力的迷迭香而得名。森林内部环境幽静，是许多自然生物和少数居民的栖息地。",
      "layout": "位于绿石城的东侧，将其大部分区域包裹其中。"
    }
  ]
}

