entries.content:
{
  "name": "绿石城",
  "parent_realm": "瑞穗联合邦，西南边境",
  "summary": "作为瑞穗联合邦面向人类诸国的门户，绿石城是一座充满活力的贸易都市。城市建筑普遍采用融入了自然元素的现代风格，街道上随处可见由魔导技术驱动的公共设施。多样的种族在此共同生活，形成了包容且繁华的社会氛围。",
  "figures": [
    {
      "name": "绿石城市政厅",
      "summary": "由民选市长领导的城市管理机构，负责维护城市基础设施、管理贸易秩序和执行联合邦法律。"
    }
  ],
  "locations": [
    {
      "name": "翡翠贸易港",
      "summary": "城市的经济命脉，是连接瑞穗联合邦与人类诸国的陆路交通枢纽。设有海关、大型货运场站以及往来两地的魔导列车总站。",
      "layout": "位于绿石城西侧，紧邻边境线。"
    },
    {
      "name": "橡木住宅区",
      "summary": "绿石城内最大的居民区，提供从单身公寓到家庭住宅等多种形式的居所。区域内配套设施完善，有公园、学校和商业街。",
      "layout": "分布于城市的北部和东部，环绕着市中心。"
    },
    {
      "name": "中央广场",
      "summary": "城市的中心地带，市政厅坐落于此。广场是市民日常休闲和举办节庆活动的主要场所，周围环绕着商店、餐厅和剧院。",
      "layout": "位于绿石城的地理中心。"
    }
  ]
}

