entries.content:
{
  "name": "迷迭香之森",
  "parent_realm": "瑞穗联合邦，绿石城周边",
  "summary": "一片环绕着绿石城的广袤森林，因遍布能散发微弱魔力的迷迭香而得名。森林内部生态系统完善，光线透过茂密的树冠变得柔和，空气中弥漫着植物的清香。这里是许多魔法生物的家园，也是寻求宁静的居民常来的地方。",
  "figures": [],
  "locations": [
    {
      "name": "筑梦小屋",
      "summary": "一栋隐藏在森林深处的双层木屋，风格雅致。作为一家提供特殊服务的店铺，其具体位置并不公开，只对持有预约的客人开放。",
      "layout": "位于森林较深处，远离主干道，周围有天然的树木作为屏障。"
    },
    {
      "name": "月光湖",
      "summary": "森林中央的一片天然湖泊，湖水清澈，在夜晚能清晰地倒映出月亮。湖边是开阔的草地，是森林动物的饮水地和居民野餐的热门地点。",
      "layout": "位于森林的中心区域。"
    },
    {
      "name": "萤火小径",
      "summary": "一条连接着森林边缘与橡木住宅区的小路。入夜后，路边的特殊苔藓会发出如同萤火虫般的微光，为夜行者提供照明。",
      "layout": "蜿蜒穿过森林东部，连接月光湖与绿石城的橡木住宅区。"
    }
  ]
}

