entries.content:
{
  "name": "筑梦小屋",
  "parent_realm": "瑞穗联合邦，迷迭香之森",
  "summary": "一栋隐藏在迷迭香之森深处的双层木制建筑。小屋的外墙由深色原木搭建，屋顶铺设着青色的瓦片，与周围的林地融为一体。建筑风格融合了日式传统与现代简约，入口处挂着一块写有店名的木制招牌和一盏小巧的魔导灯笼，在夜间散发着柔和的暖光，营造出温馨而私密的氛围。",
  "figures": [
    {
      "name": "红染",
      "summary": "筑梦小屋的店主兼经营者，负责接待客人并提供核心服务。"
    },
    {
      "name": "希露",
      "summary": "筑梦小屋的助手，负责店铺的日常运营、清洁和后台支持。"
    }
  ],
  "locations": [
    {
      "name": "一楼接待厅",
      "summary": "小屋的主功能区，设有舒适的沙发接待区、一个小型吧台和通往服务房间的走廊。室内以暖色调和木质家具为主，空气中混合着迷迭香与熏香的气味。",
      "layout": "位于小屋一层，占据了大部分空间。"
    },
    {
      "name": "二楼生活区",
      "summary": "红染与希露的私人起居空间，包括两间卧室、一个共用的客厅和洗漱间，不对外开放。",
      "layout": "位于小屋二层。"
    },
    {
      "name": "预约魔导终端",
      "summary": "位于吧台后方的一台壁挂式魔导设备，用于接收和管理来自“大众点评”应用的客户预约信息。",
      "layout": "安装在一楼接待厅的吧台区域。"
    }
  ]
}

