entries.content:
{
  "name": "中央广场",
  "parent_realm": "瑞穗联合邦，绿石城",
  "summary": "位于绿石城地理中心的广阔公共空间，地面由平整的浅色石板铺设。广场是市民日常休闲和城市举办大型节庆活动的核心场所，氛围开放而充满活力。周围环绕着各式商店、餐厅和文化设施，是城市的公共客厅。",
  "figures": [
    {
      "name": "绿石城市政厅",
      "summary": "坐落在广场北侧的庄严现代建筑，是城市的行政中枢，其钟楼的钟声为全城报时。"
    }
  ],
  "locations": [
    {
      "name": "和平缔造者纪念碑",
      "summary": "矗立于广场中央的白色方尖碑，为纪念《互不侵犯基本法案》的签订而建，碑身雕刻着代表各族团结的浮雕。",
      "layout": "位于广场的中心点。"
    },
    {
      "name": "水晶喷泉",
      "summary": "一座由魔导技术驱动的大型音乐喷泉，夜间会配合灯光进行表演，是广场上的一道亮丽风景。",
      "layout": "位于纪念碑南侧的下沉式区域。"
    },
    {
      "name": "白桦大道商业街",
      "summary": "环绕广场四周的步行商业街，两旁种满了白桦树。这里汇集了高端时装店、特色手工艺品店和多家知名餐厅。",
      "layout": "围绕着广场的主体区域。"
    }
  ]
}

